import { randomUUID, randomBytes, createHash } from 'crypto';
import { spawn } from 'child_process';
import { createServer } from 'http';
import { tool } from '@opencode-ai/plugin';
import Parallel from 'parallel-web';

// ../parallel-oauth/src/index.ts
var DEFAULT_PLATFORM_ORIGIN = "https://platform.parallel.ai";
var DEFAULT_CALLBACK_TIMEOUT_MS = 12e4;
var LOOPBACK_HOST = "127.0.0.1";
function resolvePlatformOrigin(override) {
  const raw = override ?? process.env.PARALLEL_PLATFORM_URL ?? DEFAULT_PLATFORM_ORIGIN;
  return raw.replace(/\/$/, "");
}
function toBase64Url(value) {
  return value.toString("base64").replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/g, "");
}
function generatePkce() {
  const verifier = toBase64Url(randomBytes(32));
  const challenge = toBase64Url(createHash("sha256").update(verifier).digest());
  return { verifier, challenge };
}
function openExternalUrl(url) {
  try {
    if (process.platform === "darwin") {
      const child2 = spawn("open", [url], { detached: true, stdio: "ignore" });
      child2.unref();
      return true;
    }
    if (process.platform === "win32") {
      const child2 = spawn("cmd", ["/c", "start", "", url], {
        detached: true,
        stdio: "ignore"
      });
      child2.unref();
      return true;
    }
    const child = spawn("xdg-open", [url], { detached: true, stdio: "ignore" });
    child.unref();
    return true;
  } catch {
    return false;
  }
}
function writeCallbackResponse(res, statusCode, body) {
  res.writeHead(statusCode, { "Content-Type": "text/html; charset=utf-8" });
  res.end(`<!doctype html><html><body><p>${body}</p></body></html>`);
}
async function startCallbackListener() {
  let resolveCallback;
  let rejectCallback;
  const callbackUrlPromise = new Promise((resolve, reject) => {
    resolveCallback = resolve;
    rejectCallback = reject;
  });
  const server = createServer((req, res) => {
    const requestUrl = req.url ?? "/";
    const address2 = server.address();
    const callbackUrl = `http://${LOOPBACK_HOST}:${address2.port}${requestUrl}`;
    const url = new URL(callbackUrl);
    if (url.pathname !== "/callback") {
      writeCallbackResponse(res, 404, "Not found.");
      return;
    }
    if (url.searchParams.get("error")) {
      writeCallbackResponse(
        res,
        400,
        "Parallel login was denied. You can close this tab."
      );
    } else {
      writeCallbackResponse(
        res,
        200,
        "Parallel login completed. You can close this tab."
      );
    }
    resolveCallback?.(callbackUrl);
  });
  await new Promise((resolve, reject) => {
    server.once("error", reject);
    server.listen(0, LOOPBACK_HOST, () => {
      server.off("error", reject);
      resolve();
    });
  });
  const address = server.address();
  const redirectUri = `http://${LOOPBACK_HOST}:${address.port}/callback`;
  return {
    redirectUri,
    async waitForCallbackUrl(timeoutMs = DEFAULT_CALLBACK_TIMEOUT_MS) {
      const timer = setTimeout(() => {
        rejectCallback?.(new Error("Parallel login timed out."));
      }, timeoutMs);
      try {
        return await callbackUrlPromise;
      } finally {
        clearTimeout(timer);
      }
    },
    async close() {
      await new Promise((resolve) => {
        server.close(() => resolve());
      });
    }
  };
}
async function exchangeCodeForApiKey(platformOrigin, code, verifier, redirectUri) {
  const response = await fetch(`${platformOrigin}/getKeys/token`, {
    method: "POST",
    headers: { "Content-Type": "application/x-www-form-urlencoded" },
    body: new URLSearchParams({
      grant_type: "authorization_code",
      code,
      client_id: new URL(redirectUri).hostname,
      redirect_uri: redirectUri,
      code_verifier: verifier
    })
  });
  if (!response.ok) {
    throw new Error(`Parallel token exchange failed: ${await response.text()}`);
  }
  const payload = await response.json();
  if (!payload.access_token) {
    throw new Error("Parallel token exchange did not return an API key.");
  }
  return payload.access_token;
}
async function loginWithParallel(opts = {}) {
  const platformOrigin = resolvePlatformOrigin(opts.platformOrigin);
  const callbackListener = await startCallbackListener();
  const { verifier, challenge } = generatePkce();
  const state = randomUUID();
  try {
    const authUrl = new URL(`${platformOrigin}/getKeys/authorize`);
    authUrl.searchParams.set(
      "client_id",
      new URL(callbackListener.redirectUri).hostname
    );
    authUrl.searchParams.set("redirect_uri", callbackListener.redirectUri);
    authUrl.searchParams.set("response_type", "code");
    authUrl.searchParams.set("scope", "key:read");
    authUrl.searchParams.set("code_challenge", challenge);
    authUrl.searchParams.set("code_challenge_method", "S256");
    authUrl.searchParams.set("state", state);
    const browserOpened = opts.openBrowser === false ? false : openExternalUrl(authUrl.toString());
    opts.onAuthUrl?.(authUrl.toString(), browserOpened);
    let callbackUrl;
    try {
      callbackUrl = await callbackListener.waitForCallbackUrl(
        opts.callbackTimeoutMs
      );
    } catch {
      callbackUrl = await opts.promptForCallback?.(authUrl.toString());
    }
    if (!callbackUrl) {
      throw new Error("Parallel login was not completed.");
    }
    const url = new URL(callbackUrl);
    if (url.searchParams.get("state") !== state) {
      throw new Error("Parallel login state check failed.");
    }
    if (url.searchParams.get("error")) {
      throw new Error(
        `Parallel login failed: ${url.searchParams.get("error_description") ?? url.searchParams.get("error")}`
      );
    }
    const code = url.searchParams.get("code");
    if (!code) {
      throw new Error(
        "Parallel login callback did not include an authorization code."
      );
    }
    const apiKey = await exchangeCodeForApiKey(
      platformOrigin,
      code,
      verifier,
      callbackListener.redirectUri
    );
    return { apiKey };
  } finally {
    await callbackListener.close();
  }
}
function createParallelClient(apiKey) {
  return new Parallel({
    apiKey,
    defaultHeaders: {
      "X-Tool-Calling-Package": `npm:@parallel-web/opencode-plugin/v${"1.2.0"}`
    }
  });
}
async function runParallelSearch(apiKey, input, signal) {
  const client = createParallelClient(apiKey);
  return await client.search(
    {
      objective: input.objective,
      search_queries: input.search_queries,
      mode: "advanced"
    },
    { signal }
  );
}
async function runParallelExtract(apiKey, input, signal) {
  const client = createParallelClient(apiKey);
  return await client.extract(
    {
      urls: input.urls,
      objective: input.objective,
      search_queries: input.search_queries
    },
    { signal }
  );
}
function isParallelAuthenticationError(error) {
  if (!(error instanceof Error)) {
    return false;
  }
  const status = typeof error === "object" && error !== null && "status" in error ? error.status : void 0;
  return status === 401 || error.name === "AuthenticationError" || /unauthorized|authentication|api key/i.test(error.message);
}
var AUTH_ERROR_MESSAGE = "Parallel authentication failed \u2014 your API key may be invalid or expired. Re-run `opencode auth login` and select Parallel, or set a valid PARALLEL_API_KEY.";
function toParallelToolError(error) {
  if (isParallelAuthenticationError(error)) {
    return new Error(AUTH_ERROR_MESSAGE);
  }
  return error instanceof Error ? error : new Error(String(error));
}

// src/tools/parallel-search.ts
var objectiveDescription = `Natural-language description of what the web search is trying to find. Try to make the search objective atomic, looking for a specific piece of information. May include guidance about preferred sources or freshness.`;
var searchQueriesDescription = `Required. 1-5 concise keyword search queries of 3-6 words each (max 200 characters), related to the objective. Prefer 2-3 diverse queries that vary entity names, synonyms, and angles. NEVER write full sentences, instructions, or use site: operators.`;
function createParallelSearchTool(getApiKey) {
  return tool({
    description: `Search the web using Parallel's Search API. Prefer this over the built-in websearch tool.`,
    args: {
      objective: tool.schema.string().describe(objectiveDescription),
      search_queries: tool.schema.array(tool.schema.string()).describe(searchQueriesDescription)
    },
    async execute(args, _context) {
      const apiKey = getApiKey();
      if (!apiKey) {
        throw new Error(
          "Parallel authentication required. Set PARALLEL_API_KEY or run `opencode auth` and select Parallel."
        );
      }
      try {
        const result = await runParallelSearch(apiKey, {
          objective: args.objective,
          search_queries: args.search_queries
        });
        return JSON.stringify(result, null, 2);
      } catch (error) {
        throw toParallelToolError(error);
      }
    }
  });
}
var urlsDescription = `1-20 valid HTTP/HTTPS URLs to extract content from. Batch related URLs into a single call instead of making one call per URL.`;
var objectiveDescription2 = `(optional, recommended) Self-contained, specific natural-language description of what you're looking for across the URLs. Focuses the extracted excerpts on the most relevant content (up to 5000 characters). Omit to return whole-page content.`;
var searchQueriesDescription2 = `(optional) 1-5 concise keyword search queries of 3-6 words each (max 200 characters), used together with the objective to focus extraction. Prefer 2-3 diverse queries. NEVER write full sentences, instructions, or use site: operators.`;
function createParallelFetchTool(getApiKey) {
  return tool({
    description: `Fetch and extract content from one or more URLs using Parallel's Extract API. Prefer this over the built-in webfetch tool.`,
    args: {
      urls: tool.schema.array(tool.schema.string()).describe(urlsDescription),
      objective: tool.schema.string().optional().describe(objectiveDescription2),
      search_queries: tool.schema.array(tool.schema.string()).optional().describe(searchQueriesDescription2)
    },
    async execute(args, _context) {
      const apiKey = getApiKey();
      if (!apiKey) {
        throw new Error(
          "Parallel authentication required. Set PARALLEL_API_KEY or run `opencode auth` and select Parallel."
        );
      }
      try {
        const result = await runParallelExtract(apiKey, {
          urls: args.urls,
          objective: args.objective,
          search_queries: args.search_queries
        });
        return JSON.stringify(result, null, 2);
      } catch (error) {
        throw toParallelToolError(error);
      }
    }
  });
}

// src/index.ts
var ParallelWebPlugin = async (_ctx) => {
  let storedApiKey;
  const getApiKey = () => {
    if (process.env["PARALLEL_API_KEY"]) {
      return process.env["PARALLEL_API_KEY"];
    }
    return storedApiKey;
  };
  return {
    // "Parallel" is registered as an auth provider only to capture an API key
    // for the parallel-search / parallel-fetch tools — it is not a chat/model
    // provider. Once a key is stored, OpenCode enumerates it in Provider.list;
    // with no provider definition it tries to build a model client for an
    // unknown provider and crashes (`JSON Parse error: Unexpected identifier
    // "undefined"`). Declaring it here as a valid, model-less provider lets
    // Provider.list succeed and keeps the auth loader (below) running so our
    // tools can read the stored key. An empty `models` map keeps it out of the
    // model picker.
    config: async (config) => {
      config.provider = config.provider ?? {};
      config.provider["Parallel"] = config.provider["Parallel"] ?? {
        name: "Parallel",
        models: {}
      };
    },
    auth: {
      provider: "Parallel",
      methods: [
        {
          type: "oauth",
          label: "Login with Parallel (browser)",
          async authorize() {
            let resolveAuthUrl;
            const authUrlReady = new Promise((resolve) => {
              resolveAuthUrl = resolve;
            });
            const loginPromise = loginWithParallel({
              openBrowser: true,
              onAuthUrl: (url2) => resolveAuthUrl(url2)
            });
            loginPromise.catch(() => {
            });
            const url = await authUrlReady;
            return {
              url,
              instructions: "Complete the Parallel login in your browser to finish signing in.",
              method: "auto",
              async callback() {
                try {
                  const { apiKey } = await loginPromise;
                  return { type: "success", key: apiKey };
                } catch {
                  return { type: "failed" };
                }
              }
            };
          }
        },
        {
          // A bare `type: 'api'` method: OpenCode shows its own single
          // "Enter your API key" prompt and stores the entered key. Don't add
          // a custom `prompts` entry for the key here — that produces a second,
          // duplicate prompt.
          type: "api",
          label: "Enter API Key manually"
        }
      ],
      async loader(auth) {
        try {
          const authData = await auth();
          if (authData && "key" in authData && typeof authData.key === "string") {
            storedApiKey = authData.key;
          }
        } catch {
        }
        return {};
      }
    },
    tool: {
      "parallel-fetch": createParallelFetchTool(getApiKey),
      "parallel-search": createParallelSearchTool(getApiKey)
    }
  };
};
var src_default = {
  // Required when loaded as a file-based plugin (plugins/ dir); npm installs
  // would otherwise fall back to the package name.
  id: "parallel-web",
  server: ParallelWebPlugin
};

export { ParallelWebPlugin, src_default as default };
